import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, Router, NavigationEnd } from '@angular/router';
import { filter } from 'rxjs/operators';
import { AuthService } from '../../../core/services/auth.service';
import { ThemeService } from '../../../core/services/theme.service';
import { ExportService } from '../../../services/export.service';
import { TranslationPipe } from '../../../core/i18n/translation.pipe';
import { LangSwitchComponent } from '../../../core/i18n/lang-switch.component';

@Component({
  selector: 'app-navbar',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslationPipe, LangSwitchComponent],
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.scss']
})
export class NavbarComponent implements OnInit {
  isLoggedIn = false;
  isAdmin = false;
  isMobileMenuOpen = false;
  isDarkMode = false;
  userName: string | null = null;
  pageTitleKey = 'navbar.overview';

  constructor(
    private authService: AuthService,
    private themeService: ThemeService,
    private exportService: ExportService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.checkAuthStatus();
    this.checkThemeMode();
    this.updatePageTitle(this.router.url);

    this.authService.isLoggedIn$.subscribe((loggedIn: boolean) => {
      this.isLoggedIn = loggedIn;
      if (loggedIn) {
        const userData = this.authService.getUserData();
        if (userData) {
          this.userName = userData.nome;
          this.isAdmin = userData.role === 1;
        }
      }
    });

    this.router.events
      .pipe(filter((event): event is NavigationEnd => event instanceof NavigationEnd))
      .subscribe((event: NavigationEnd) => {
        this.updatePageTitle(event.urlAfterRedirects);
      });

    this.themeService.isDarkMode$.subscribe((isDark: boolean) => {
      this.isDarkMode = isDark;
    });
  }

  private checkAuthStatus(): void {
    this.isLoggedIn = this.authService.isAuthenticated();
    if (this.isLoggedIn) {
      const userData = this.authService.getUserData();
      if (userData) {
        this.userName = userData.nome;
        this.isAdmin = userData.role === 1;
      }
    }
  }

  private checkThemeMode(): void {
    this.isDarkMode = this.themeService.isDark();
  }

  toggleTheme(): void {
    this.themeService.toggleTheme();
  }

  toggleMobileMenu(): void {
    this.isMobileMenuOpen = !this.isMobileMenuOpen;
  }

  closeMobileMenu(): void {
    this.isMobileMenuOpen = false;
  }

  logout(): void {
    this.authService.logout();
    this.closeMobileMenu();
    this.router.navigate(['/login']);
  }

  exportCSV(): void {
    const url = this.isAdmin
      ? 'http://localhost/gfp/backend/api/admin/exportar/usuarios'
      : 'http://localhost/gfp/backend/api/exportar/csv';
    const fileName = this.isAdmin ? 'usuarios_sistema.csv' : 'extrato_financeiro.csv';

    this.exportService.exportarCsv(fileName, url).catch((error: Error) => {
      console.error('Erro ao exportar:', error);
    });
  }

  private updatePageTitle(url: string): void {
    if (url.startsWith('/admin')) {
      this.pageTitleKey = 'navbar.administration';
    } else if (url.startsWith('/transacoes')) {
      this.pageTitleKey = 'navbar.transactions';
    } else if (url.startsWith('/categorias')) {
      this.pageTitleKey = 'navbar.categories';
    } else {
      this.pageTitleKey = 'navbar.overview';
    }
  }
}
<aside *ngIf="isLoggedIn" class="sidebar">
  <a [routerLink]="isAdmin ? '/admin' : '/dashboard'" class="brand" (click)="closeMobileMenu()">
    <span class="brand-mark">FS</span>
    <div class="brand-text">
      <strong>{{ 'common.appName' | t }}</strong>
      <span>{{ 'navbar.financialCloud' | t }}</span>
    </div>
  </a>

  <nav class="side-nav">
    <ng-container *ngIf="!isAdmin; else adminNav">
      <a routerLink="/dashboard" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>{{ 'navbar.overview' | t }}</span></a>
      <a routerLink="/transacoes" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>{{ 'navbar.transactions' | t }}</span></a>
      <a routerLink="/categorias" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>{{ 'navbar.categories' | t }}</span></a>
    </ng-container>
    <ng-template #adminNav>
      <a routerLink="/admin" routerLinkActive="active" class="side-link" (click)="closeMobileMenu()"><span>{{ 'navbar.administration' | t }}</span></a>
    </ng-template>
  </nav>

  <div class="sidebar-footer">
    <button class="side-action" (click)="exportCSV()" [title]="'navbar.exportCsvTitle' | t">{{ 'common.exportCsv' | t }}</button>
    <button class="side-action danger" (click)="logout()" [title]="'navbar.logoutTitle' | t">{{ 'common.logout' | t }}</button>
  </div>
</aside>

<header class="topbar" [class.with-sidebar]="isLoggedIn">
  <div class="topbar-left">
    <h1>{{ pageTitleKey | t }}</h1>
    <p *ngIf="isLoggedIn">{{ 'navbar.greeting' | t }}, <strong>{{ userName }}</strong></p>
  </div>

  <div class="topbar-right">
    <app-lang-switch></app-lang-switch>
    <a *ngIf="!isLoggedIn" routerLink="/login" class="auth-link">{{ 'common.login' | t }}</a>
    <a *ngIf="!isLoggedIn" routerLink="/register" class="auth-link primary">{{ 'common.register' | t }}</a>

    <button *ngIf="isLoggedIn" class="mobile-menu-btn" [class.active]="isMobileMenuOpen" (click)="toggleMobileMenu()" [attr.aria-label]="'navbar.openMenuAria' | t">
      {{ 'common.menu' | t }}
    </button>

    <button class="theme-toggle" (click)="toggleTheme()" [title]="(isDarkMode ? 'common.lightMode' : 'common.darkMode') | t">
      {{ 'common.theme' | t }}
    </button>
  </div>
</header>

<div *ngIf="isLoggedIn" class="mobile-drawer" [class.open]="isMobileMenuOpen">
  <ng-container *ngIf="!isAdmin; else adminDrawerNav">
    <a routerLink="/dashboard" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">{{ 'navbar.overview' | t }}</a>
    <a routerLink="/transacoes" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">{{ 'navbar.transactions' | t }}</a>
    <a routerLink="/categorias" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">{{ 'navbar.categories' | t }}</a>
  </ng-container>
  <ng-template #adminDrawerNav>
    <a routerLink="/admin" routerLinkActive="active" class="drawer-link" (click)="closeMobileMenu()">{{ 'navbar.administration' | t }}</a>
  </ng-template>
  <button class="drawer-link" (click)="exportCSV(); closeMobileMenu()">{{ 'common.exportCsv' | t }}</button>
  <button class="drawer-link danger" (click)="logout()">{{ 'common.logout' | t }}</button>
</div>

<nav *ngIf="isLoggedIn" class="bottom-nav">
  <ng-container *ngIf="!isAdmin; else adminBottomNav">
    <a routerLink="/dashboard" routerLinkActive="active" class="bottom-link"><span>{{ 'common.start' | t }}</span></a>
    <a routerLink="/transacoes" routerLinkActive="active" class="bottom-link"><span>{{ 'navbar.transactions' | t }}</span></a>
    <a routerLink="/categorias" routerLinkActive="active" class="bottom-link"><span>{{ 'navbar.categories' | t }}</span></a>
  </ng-container>
